-- FitSync AI PostgreSQL 17 Schema (Generated from fitsync_db)

CREATE TABLE IF NOT EXISTS "account_deletion_requests" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "user_id" BIGINT NOT NULL,
  "reason" TEXT,
  "requested_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "scheduled_for" TIMESTAMP NOT NULL,
  "cancelled_at" TIMESTAMP,
  PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "allergens" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "name" VARCHAR(100) NOT NULL,
  "icon" VARCHAR(50),
  PRIMARY KEY ("id"),
  CONSTRAINT "uq_allergens_name" UNIQUE ("name")
);

CREATE TABLE IF NOT EXISTS "attendance" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "user_id" BIGINT NOT NULL,
  "gym_id" BIGINT NOT NULL,
  "check_in_time" TIMESTAMP NOT NULL,
  "check_out_time" TIMESTAMP,
  "check_in_method" VARCHAR(60) NOT NULL DEFAULT 'qr_code',
  "status" VARCHAR(60) NOT NULL DEFAULT 'verified',
  "notes" VARCHAR(255),
  PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "audit_logs" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "user_id" BIGINT,
  "action" VARCHAR(100) NOT NULL,
  "entity_table" VARCHAR(100) NOT NULL,
  "entity_id" BIGINT,
  "details" TEXT,
  "ip_address" VARCHAR(45),
  "created_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "auth_tokens" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "user_id" BIGINT NOT NULL,
  "purpose" VARCHAR(60) NOT NULL,
  "token_hash" VARCHAR(255) NOT NULL,
  "new_email" VARCHAR(191),
  "expires_at" TIMESTAMP NOT NULL,
  "used_at" TIMESTAMP,
  "created_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id"),
  CONSTRAINT "uq_auth_tokens_token_hash" UNIQUE ("token_hash")
);

CREATE TABLE IF NOT EXISTS "body_measurements" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "user_id" BIGINT NOT NULL,
  "recorded_at" DATE NOT NULL,
  "weight_kg" NUMERIC(5,2) NOT NULL,
  "body_fat_pct" NUMERIC(4,1),
  "chest_cm" NUMERIC(5,2),
  "waist_cm" NUMERIC(5,2),
  "hips_cm" NUMERIC(5,2),
  "arms_cm" NUMERIC(5,2),
  "thighs_cm" NUMERIC(5,2),
  "calves_cm" NUMERIC(5,2),
  "notes" TEXT,
  "created_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "body_regions" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "name" VARCHAR(100) NOT NULL,
  "code" VARCHAR(50) NOT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "uq_body_regions_name" UNIQUE ("name"),
  CONSTRAINT "uq_body_regions_code" UNIQUE ("code")
);

CREATE TABLE IF NOT EXISTS "complaints" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
