  "created_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id"),
  CONSTRAINT "uq_conversations_uq_conversation_peers" UNIQUE ("participant_one_id", "participant_two_id")
);

CREATE TABLE IF NOT EXISTS "dietary_tags" (
