  CONSTRAINT "uq_user_roles_uq_user_role" UNIQUE ("user_id", "role")
);

CREATE TABLE IF NOT EXISTS "user_sessions" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
