);

CREATE TABLE IF NOT EXISTS "verification_requests" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "user_id" BIGINT NOT NULL,
  "status" VARCHAR(60) NOT NULL DEFAULT 'pending',
