  PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "workout_feedback" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "session_id" BIGINT NOT NULL,
  "assignment_id" BIGINT,
