  "author_trainer_id" BIGINT,
  "is_template" SMALLINT NOT NULL DEFAULT 0,
  "is_archived" SMALLINT NOT NULL DEFAULT 0,
  "difficulty" VARCHAR(60) NOT NULL DEFAULT 'intermediate',
  "days_per_week" INTEGER NOT NULL DEFAULT 4,
  "goal" VARCHAR(60) NOT NULL DEFAULT 'hypertrophy',
  "split_type" VARCHAR(60) NOT NULL DEFAULT 'Custom Split',
  "duration_weeks" INTEGER NOT NULL DEFAULT 4,
  "trainer_instructions" TEXT,
  "source_template_id" BIGINT,
  "created_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "workout_sessions" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "user_id" BIGINT NOT NULL,
  "plan_day_id" BIGINT,
  "assignment_id" BIGINT,
  "gym_id" BIGINT,
  "session_date" DATE NOT NULL,
  "start_time" TIMESTAMP NOT NULL,
  "end_time" TIMESTAMP,
  "duration_minutes" INTEGER,
  "status" VARCHAR(60) NOT NULL DEFAULT 'completed',
  "paused_at" TIMESTAMP,
  "elapsed_seconds" INTEGER NOT NULL DEFAULT 0,
  "total_volume_kg" NUMERIC(10,2) NOT NULL DEFAULT 0.00,
  "total_sets_completed" INTEGER NOT NULL DEFAULT 0,
  "perceived_rpe" INTEGER,
  "notes" TEXT,
  "created_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);

